                        trigger: '触发式效果',
                        discard_lifecycle: '弃牌触发效果',
                        desire_overflow_dynamic_payload: '欲望满溢的动态效果',
                        desire_overflow_payload: '欲望满溢效果',
                        container_formula: '容器数值公式',
                        apply_status: '施加状态',
                        remove_status: '移除状态',
                        modify: '修改数值',
